window.__syncAll63Consensus = async function(startIdx = 0, count = 63, delayMs = 150) {
  const sids = COVIDENCE_63_SIDS.slice(startIdx, startIdx + count);
  const csrfToken = document.querySelector('meta[name="csrf-token"]')?.content;
  const results = [];

  console.log(`Starting consensus sync for ${sids.length} studies (start: ${startIdx})...`);

  for (let i = 0; i < sids.length; i++) {
    const sid = sids[i];
    const gt = AUDITED_GROUND_TRUTH[sid];
    const currentIdx = startIdx + i + 1;
    if (!gt) {
      results.push({ index: currentIdx, sid, status: 'error', error: 'No ground truth found' });
      continue;
    }

    try {
      // 1. Fetch HTML to extract deId
      const htmlRes = await fetch(`/reviews/799962/review_studies/${sid}/data_extractions`);
      if (!htmlRes.ok) throw new Error(`HTML fetch failed: ${htmlRes.status}`);
      const html = await htmlRes.text();
      const deMatch = html.match(/data_extractions\/(\d+)/);
      if (!deMatch) throw new Error('Could not parse deId from HTML');
      const deId = deMatch[1];

      // 2. Fetch data extraction JSON for consensus
      const consRes = await fetch(`/reviews/799962/review_studies/${sid}/data_extractions/${deId}`, {
        headers: { 'Accept': 'application/json' }
      });
      if (!consRes.ok) throw new Error(`Consensus fetch failed: ${consRes.status}`);
      const consData = await consRes.json();

      // 3. Fetch API data for reviewer
      const apiRes = await fetch(`/api/extraction/v1/review_studies/${sid}/data_extraction`);
      if (!apiRes.ok) throw new Error(`API fetch failed: ${apiRes.status}`);
      const apiData = await apiRes.json();

      // 4. Identify arm1 and arm2
      let arm1 = null, arm2 = null;
      const named = (consData.arms || []).filter(a => a.intervention_group !== null);
      if (named.length >= 2) {
        named.sort((a, b) => a.position - b.position);
        arm1 = named[0].id;
        arm2 = named[1].id;
      } else if (consData.arms && consData.arms.length === 2) {
        arm1 = consData.arms[0].id;
        arm2 = consData.arms[1].id;
      } else if (consData.arms && consData.arms.length > 2) {
        const armCounts = {};
        (consData.baseline_characteristics || []).forEach(bc => {
          (bc.results || []).forEach(r => {
            if (r.arm_id) armCounts[r.arm_id] = (armCounts[r.arm_id] || 0) + 1;
          });
        });
        const sortedIds = Object.keys(armCounts).sort((a, b) => armCounts[b] - armCounts[a]);
        if (sortedIds.length >= 2) {
          arm1 = Number(sortedIds[0]);
          arm2 = Number(sortedIds[1]);
        } else {
          arm1 = consData.arms[0].id;
          arm2 = consData.arms[1].id;
        }
      }

      if (!arm1 || !arm2) throw new Error('Could not identify arm1 and arm2');

      let bcCount = 0;
      let icCount = 0;

      // 5. Update Baseline Characteristics
      for (const bc of consData.baseline_characteristics) {
        const name = bc.name.toLowerCase();
        let val1 = null, val2 = null;

        if (name.includes('mean age') || name.includes('age')) {
          val1 = gt.arm1_age; val2 = gt.arm2_age;
        } else if (name.includes('number randomized')) {
          val1 = String(gt.arm1_n); val2 = String(gt.arm2_n);
        } else if (name.includes('number analysed') || name.includes('analysed')) {
          val1 = String(gt.arm1_n); val2 = String(gt.arm2_n);
        } else if (name.includes('female')) {
          val1 = gt.arm1_female; val2 = gt.arm2_female;
        } else if (name.includes('bmi') || name.includes('weight')) {
          val1 = gt.arm1_bmi; val2 = gt.arm2_bmi;
        } else if (name.includes('asa')) {
          val1 = gt.arm1_asa; val2 = gt.arm2_asa;
        } else if (name.includes('pain')) {
          val1 = 'not reported'; val2 = 'not reported';
        } else if (name.includes('opioid')) {
          val1 = 'not reported'; val2 = 'not reported';
        }

        if (val1 && val2) {
          // A. Reviewer PUT
          const apiBc = apiData.baseline_characteristics ? apiData.baseline_characteristics.find(b => b.id === bc.id) : null;
          if (apiBc) {
            await fetch(`/api/extraction/v1/review_studies/${sid}/data_extraction/baseline_characteristics/${bc.id}/results`, {
              method: 'PUT',
              headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrfToken },
              body: JSON.stringify({ arm_id: arm1, value: String(val1) })
            });
            await fetch(`/api/extraction/v1/review_studies/${sid}/data_extraction/baseline_characteristics/${bc.id}/results`, {
              method: 'PUT',
              headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrfToken },
              body: JSON.stringify({ arm_id: arm2, value: String(val2) })
            });
          }

          // B. Consensus PUT or POST
          const existingCons1 = (bc.results || []).find(r => r.reviewer_id === 0 && r.arm_id === arm1);
          if (existingCons1) {
            await fetch(`/reviews/799962/review_studies/${sid}/data_extractions/${deId}/characteristic_results/${existingCons1.id}`, {
              method: 'PUT',
              headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrfToken },
              body: JSON.stringify({ value: String(val1) })
            });
          } else {
            await fetch(`/reviews/799962/review_studies/${sid}/data_extractions/${deId}/characteristic_results`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrfToken },
              body: JSON.stringify({ arm_id: arm1, reviewer_id: 0, characteristic_id: bc.id, value: String(val1) })
            });
          }

          const existingCons2 = (bc.results || []).find(r => r.reviewer_id === 0 && r.arm_id === arm2);
          if (existingCons2) {
            await fetch(`/reviews/799962/review_studies/${sid}/data_extractions/${deId}/characteristic_results/${existingCons2.id}`, {
              method: 'PUT',
              headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrfToken },
              body: JSON.stringify({ value: String(val2) })
            });
          } else {
            await fetch(`/reviews/799962/review_studies/${sid}/data_extractions/${deId}/characteristic_results`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrfToken },
              body: JSON.stringify({ arm_id: arm2, reviewer_id: 0, characteristic_id: bc.id, value: String(val2) })
            });
          }

          bcCount += 2;
        }
      }

      // 6. Update STRICTA Acupoints
      const acupointChar = (consData.intervention_characteristics || []).find(ic => ic.name.toLowerCase().includes('acupoints used'));
      if (acupointChar && gt.acupoints) {
        const pts1 = gt.acupoints;
        const pts2 = 'Not applicable';

        const existingCons1 = (acupointChar.results || []).find(r => r.reviewer_id === 0 && r.arm_id === arm1);
        if (existingCons1) {
          await fetch(`/reviews/799962/review_studies/${sid}/data_extractions/${deId}/characteristic_results/${existingCons1.id}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrfToken },
            body: JSON.stringify({ value: pts1 })
          });
        } else {
          await fetch(`/reviews/799962/review_studies/${sid}/data_extractions/${deId}/characteristic_results`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrfToken },
            body: JSON.stringify({ arm_id: arm1, reviewer_id: 0, characteristic_id: acupointChar.id, value: pts1 })
          });
        }

        const existingCons2 = (acupointChar.results || []).find(r => r.reviewer_id === 0 && r.arm_id === arm2);
        if (existingCons2) {
          await fetch(`/reviews/799962/review_studies/${sid}/data_extractions/${deId}/characteristic_results/${existingCons2.id}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrfToken },
            body: JSON.stringify({ value: pts2 })
          });
        } else {
          await fetch(`/reviews/799962/review_studies/${sid}/data_extractions/${deId}/characteristic_results`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': csrfToken },
            body: JSON.stringify({ arm_id: arm2, reviewer_id: 0, characteristic_id: acupointChar.id, value: pts2 })
          });
        }
        icCount += 2;
      }

      results.push({ index: currentIdx, sid, key: gt.key, bcCount, icCount, status: 'ok' });
      console.log(`[${currentIdx}/${sids.length + startIdx}] Synced ${gt.key}: ${bcCount} BC, ${icCount} IC`);
    } catch (err) {
      results.push({ index: currentIdx, sid, key: gt.key, status: 'error', error: err.message });
      console.error(`[${currentIdx}] Error syncing ${sid}:`, err);
    }

    if (delayMs > 0 && i < sids.length - 1) {
      await new Promise(r => setTimeout(r, delayMs));
    }
  }

  return results;
};
